"""Value model, three-valued logic, comparison and arithmetic."""

from .errors import TypeMismatchError


def type_of(v: object) -> str:
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "BOOL"
    if isinstance(v, int):
        return "INT"
    if isinstance(v, float):
        return "FLOAT"
    if isinstance(v, str):
        return "TEXT"
    raise TypeMismatchError(f"unsupported value {v!r}")


def is_numeric(v: object) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _check_logical(v: object) -> None:
    if v is not None and not isinstance(v, bool):
        raise TypeMismatchError(f"expected BOOL or NULL, got {type_of(v)}")


def and_(a: bool | None, b: bool | None) -> bool | None:
    _check_logical(a)
    _check_logical(b)
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or_(a: bool | None, b: bool | None) -> bool | None:
    _check_logical(a)
    _check_logical(b)
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not_(a: bool | None) -> bool | None:
    _check_logical(a)
    return None if a is None else (not a)


def _check_comparable(a: object, b: object) -> None:
    if is_numeric(a) and is_numeric(b):
        return
    if isinstance(a, str) and isinstance(b, str):
        return
    if isinstance(a, bool) and isinstance(b, bool):
        return
    raise TypeMismatchError(f"cannot compare {type_of(a)} with {type_of(b)}")


def compare_eq(a: object, b: object) -> bool | None:
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a == b


def compare_lt(a: object, b: object) -> bool | None:
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a < b  # type: ignore[operator]


def arith(op: str, a: object, b: object) -> object:
    if op not in ("+", "-", "*", "/", "%"):
        raise ValueError(f"unknown arithmetic operator {op!r}")
    if a is None or b is None:
        return None
    if not (is_numeric(a) and is_numeric(b)):
        raise TypeMismatchError(
            f"operator {op} needs numeric operands, got {type_of(a)} and {type_of(b)}"
        )
    if op == "%" and not (isinstance(a, int) and isinstance(b, int)):
        raise TypeMismatchError("operator % requires INT operands")
    if op in ("/", "%") and b == 0:
        return None
    if op == "+":
        return a + b  # type: ignore[operator]
    if op == "-":
        return a - b  # type: ignore[operator]
    if op == "*":
        return a * b  # type: ignore[operator]
    if op == "/":
        return a / b  # type: ignore[operator]
    return a % b  # type: ignore[operator]


def negate(a: object) -> object:
    if a is None:
        return None
    if not is_numeric(a):
        raise TypeMismatchError(f"cannot negate {type_of(a)}")
    return -a  # type: ignore[operator]

"""Schema layer: Column and Table."""

import dataclasses

from .errors import SchemaError, UnknownColumnError

COLUMN_TYPES = ("INT", "FLOAT", "TEXT", "BOOL")


@dataclasses.dataclass(frozen=True)
class Column:
    name: str
    type: str


def _coerce(value: object, ctype: str, where: str) -> object:
    if value is None:
        return None
    if ctype == "BOOL":
        ok = isinstance(value, bool)
    elif ctype == "INT":
        ok = isinstance(value, int) and not isinstance(value, bool)
    elif ctype == "FLOAT":
        ok = isinstance(value, (int, float)) and not isinstance(value, bool)
        if ok:
            return float(value)  # type: ignore[arg-type]
    else:
        ok = isinstance(value, str)
    if not ok:
        raise SchemaError(f"{where}: {value!r} is not a valid {ctype}")
    return value


class Table:
    def __init__(self, name: str, columns: list[Column], rows: list[list[object]]) -> None:
        if not columns:
            raise SchemaError("a table needs at least one column")
        seen: set[str] = set()
        for col in columns:
            if col.name in seen:
                raise SchemaError(f"duplicate column name {col.name!r}")
            seen.add(col.name)
            if col.type not in COLUMN_TYPES:
                raise SchemaError(f"unknown column type {col.type!r}")
        self._name = name
        self._columns = list(columns)
        self._rows = [self._check_row(i, r) for i, r in enumerate(rows)]

    def _check_row(self, index: int, row: list[object]) -> list[object]:
        if len(row) != len(self._columns):
            raise SchemaError(
                f"row {index} has {len(row)} cells, expected {len(self._columns)}"
            )
        return [
            _coerce(v, c.type, f"row {index}, column {c.name!r}")
            for v, c in zip(row, self._columns)
        ]

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return self._columns

    @property
    def rows(self) -> list[list[object]]:
        return self._rows

    def column_index(self, name: str) -> int:
        for i, col in enumerate(self._columns):
            if col.name == name:
                return i
        raise SchemaError(f"unknown column {name!r} in table {self._name!r}")


# UnknownColumnError is imported for callers that want a schema-level alias.
__all__ = ["Column", "Table", "COLUMN_TYPES", "UnknownColumnError"]

"""Lexer for the microdb query language."""

import dataclasses

from .errors import LexError

KEYWORDS = frozenset(
    "SELECT DISTINCT FROM INNER LEFT JOIN ON WHERE GROUP BY HAVING ORDER ASC DESC "
    "LIMIT OFFSET AS AND OR NOT IS NULL TRUE FALSE".split()
)
_DIGITS = "0123456789"
_IDENT_START = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_"
_IDENT_PART = _IDENT_START + _DIGITS
_SPACE = " \t\r\n\f\v"
_TWO_CHAR_OPS = ("<=", ">=", "<>")
_ONE_CHAR_OPS = "=<>+-*/%(),."


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str  # INT FLOAT TEXT IDENT KW OP EOF
    value: object
    start: int
    end: int


def _read_text(source: str, i: int) -> tuple[Token, int]:
    n = len(source)
    j = i + 1
    parts: list[str] = []
    while j < n:
        if source[j] == "'":
            if j + 1 < n and source[j + 1] == "'":
                parts.append("'")
                j += 2
                continue
            return Token("TEXT", "".join(parts), i, j + 1), j + 1
        parts.append(source[j])
        j += 1
    raise LexError("unterminated text literal", i)


def _skip_digits(source: str, j: int) -> int:
    while j < len(source) and source[j] in _DIGITS:
        j += 1
    return j


def _read_number(source: str, i: int) -> tuple[Token, int]:
    n = len(source)
    j = _skip_digits(source, i)
    is_float = False
    if j < n and source[j] == ".":
        is_float = True
        j = _skip_digits(source, j + 1)
    if j < n and source[j] in "eE":
        k = j + 1
        if k < n and source[k] in "+-":
            k += 1
        if k < n and source[k] in _DIGITS:
            j = _skip_digits(source, k)
            is_float = True
    text = source[i:j]
    if is_float:
        return Token("FLOAT", float(text), i, j), j
    return Token("INT", int(text), i, j), j


def _read_ident(source: str, i: int) -> tuple[Token, int]:
    j = i + 1
    while j < len(source) and source[j] in _IDENT_PART:
        j += 1
    word = source[i:j]
    if word.upper() in KEYWORDS:
        return Token("KW", word.upper(), i, j), j
    return Token("IDENT", word, i, j), j


def _read_operator(source: str, i: int) -> tuple[Token, int]:
    two = source[i:i + 2]
    if two in _TWO_CHAR_OPS:
        return Token("OP", two, i, i + 2), i + 2
    if source[i] in _ONE_CHAR_OPS:
        return Token("OP", source[i], i, i + 1), i + 1
    raise LexError(f"unexpected character {source[i]!r}", i)


def _next_token(source: str, i: int) -> tuple[Token, int]:
    ch = source[i]
    if ch == "'":
        return _read_text(source, i)
    following = source[i + 1:i + 2]
    if ch in _DIGITS or (ch == "." and following != "" and following in _DIGITS):
        return _read_number(source, i)
    if ch in _IDENT_START:
        return _read_ident(source, i)
    return _read_operator(source, i)


def tokenize(source: str) -> list[Token]:
    tokens: list[Token] = []
    i = 0
    n = len(source)
    while i < n:
        if source[i] in _SPACE:
            i += 1
        elif source.startswith("--", i):
            end = source.find("\n", i)
            i = n if end < 0 else end + 1
        else:
            token, i = _next_token(source, i)
            tokens.append(token)
    tokens.append(Token("EOF", None, n, n))
    return tokens

