@dataclasses.dataclass(frozen=True)
class SelectItem:
    expr: object
    alias: str | None
    text: str


@dataclasses.dataclass(frozen=True)
class OrderItem:
    expr: object
    desc: bool


@dataclasses.dataclass(frozen=True)
class JoinClause:
    kind: str  # "INNER" or "LEFT"
    table: str
    on: object


@dataclasses.dataclass(frozen=True)
class Query:
    distinct: bool
    items: tuple
    table: str
    join: JoinClause | None
    where: object | None
    group_by: tuple
    having: object | None
    order_by: tuple
    limit: int | None
    offset: int | None


_COMPARISONS = ("=", "<>", "<", "<=", ">", ">=")


class _Parser:
    def __init__(self, source: str) -> None:
        self.src = source
        self.toks = tokenize(source)
        self.pos = 0
        self.in_agg = False

    def peek(self, k: int = 0) -> Token:
        return self.toks[min(self.pos + k, len(self.toks) - 1)]

    def advance(self) -> Token:
        tok = self.peek()
        self.pos += 1
        return tok

    def fail(self, message: str, tok: Token | None = None) -> ParseError:
        tok = tok or self.peek()
        found = "end of input" if tok.kind == "EOF" else repr(self.src[tok.start:tok.end])
        return ParseError(f"{message}, found {found}", tok.start)

    def at_kw(self, *names: str, k: int = 0) -> bool:
        tok = self.peek(k)
        return tok.kind == "KW" and tok.value in names

    def at_op(self, *ops: str, k: int = 0) -> bool:
        tok = self.peek(k)
        return tok.kind == "OP" and tok.value in ops

    def accept_kw(self, name: str) -> bool:
        if self.at_kw(name):
            self.pos += 1
            return True
        return False

    def accept_op(self, op: str) -> bool:
        if self.at_op(op):
            self.pos += 1
            return True
        return False

    def expect_kw(self, name: str) -> None:
        if not self.accept_kw(name):
            raise self.fail(f"expected {name}")

    def expect_op(self, op: str) -> None:
        if not self.accept_op(op):
            raise self.fail(f"expected '{op}'")

    def ident(self, what: str) -> str:
        tok = self.peek()
        if tok.kind != "IDENT":
            raise self.fail(f"expected {what}")
        self.pos += 1
        return str(tok.value)

    def int_literal(self, what: str) -> int:
        tok = self.peek()
        if tok.kind != "INT":
            raise self.fail(f"expected integer after {what}")
        self.pos += 1
        return int(tok.value)  # type: ignore[call-overload]

    def comma_list(self, fn) -> list:
        items = [fn()]
        while self.accept_op(","):
            items.append(fn())
        return items

    # ---- query ----
    def query(self) -> Query:
        self.expect_kw("SELECT")
        distinct = self.accept_kw("DISTINCT")
        items = self.comma_list(self.select_item)
        self.expect_kw("FROM")
        table = self.ident("table name")
        join = self.join_clause()
        where = self.or_expr() if self.accept_kw("WHERE") else None
        group_by: list = []
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            group_by = self.comma_list(self.or_expr)
        having = self.or_expr() if self.accept_kw("HAVING") else None
        order_by: list = []
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            order_by = self.comma_list(self.order_item)
        limit = self.int_literal("LIMIT") if self.accept_kw("LIMIT") else None
        offset = self.int_literal("OFFSET") if self.accept_kw("OFFSET") else None
        if self.peek().kind != "EOF":
            raise self.fail("unexpected token")
        return Query(distinct, tuple(items), table, join, where, tuple(group_by),
                     having, tuple(order_by), limit, offset)

    def join_clause(self) -> JoinClause | None:
        kind = "INNER"
        if self.at_kw("INNER", "LEFT"):
            kind = str(self.advance().value)
            self.expect_kw("JOIN")
        elif not self.accept_kw("JOIN"):
            return None
        table = self.ident("table name")
        self.expect_kw("ON")
        return JoinClause(kind, table, self.or_expr())

    def select_item(self) -> SelectItem:
        if self.at_op("*"):
            self.pos += 1
            return SelectItem(Star(None), None, "*")
        if self.peek().kind == "IDENT" and self.at_op(".", k=1) and self.at_op("*", k=2):
            name = str(self.advance().value)
            self.pos += 2
            return SelectItem(Star(name), None, name + ".*")
        start = self.peek().start
        expr = self.or_expr()
        text = " ".join(self.src[start:self.toks[self.pos - 1].end].split())
        alias = self.ident("alias") if self.accept_kw("AS") else None
        return SelectItem(expr, alias, text)

    def order_item(self) -> OrderItem:
        expr = self.or_expr()
        desc = False
        if self.accept_kw("DESC"):
            desc = True
        else:
            self.accept_kw("ASC")
        return OrderItem(expr, desc)

    # ---- expressions ----
    def or_expr(self) -> object:
        node = self.and_expr()
        while self.accept_kw("OR"):
            node = Binary("OR", node, self.and_expr())
        return node

    def and_expr(self) -> object:
        node = self.not_expr()
        while self.accept_kw("AND"):
            node = Binary("AND", node, self.not_expr())
        return node

    def not_expr(self) -> object:
        if self.accept_kw("NOT"):
            return Unary("NOT", self.not_expr())
        return self.predicate()

    def predicate(self) -> object:
        node = self.additive()
        if self.at_op(*_COMPARISONS):
            op = str(self.advance().value)
            return Binary(op, node, self.additive())
        if self.accept_kw("IS"):
            negated = self.accept_kw("NOT")
            self.expect_kw("NULL")
            return IsNull(node, negated)
        return node

    def additive(self) -> object:
        node = self.multiplicative()
        while self.at_op("+", "-"):
            op = str(self.advance().value)
            node = Binary(op, node, self.multiplicative())
        return node

    def multiplicative(self) -> object:
        node = self.unary()
        while self.at_op("*", "/", "%"):
            op = str(self.advance().value)
            node = Binary(op, node, self.unary())
        return node

    def unary(self) -> object:
        if self.accept_op("-"):
            return Unary("-", self.unary())
        return self.primary()

    def primary(self) -> object:
        tok = self.peek()
        if tok.kind in ("INT", "FLOAT", "TEXT"):
            self.pos += 1
            return Literal(tok.value, tok.kind)
        if tok.kind == "KW" and tok.value in ("TRUE", "FALSE", "NULL"):
            self.pos += 1
            value = {"TRUE": True, "FALSE": False, "NULL": None}[str(tok.value)]
            return Literal(value, "NULL" if value is None else "BOOL")
        if tok.kind == "IDENT":
            return self.name_or_call()
        if self.accept_op("("):
            node = self.or_expr()
            self.expect_op(")")
            return node
        raise self.fail("expected expression")

    def name_or_call(self) -> object:
        tok = self.advance()
        if self.at_op("("):
            return self.call(tok)
        if self.accept_op("."):
            return ColumnRef(str(tok.value), self.ident("column name after '.'"))
        return ColumnRef(None, str(tok.value))

    def call(self, name_tok: Token) -> Call:
        name = str(name_tok.value).lower()
        is_agg = name in AGGREGATES
        if is_agg and self.in_agg:
            raise self.fail("aggregates cannot be nested", name_tok)
        self.expect_op("(")
        if self.at_op("*"):
            if name != "count":
                raise self.fail("'*' is only allowed in count(*)")
            self.pos += 1
            self.expect_op(")")
            return Call(name, (), True)
        previous = self.in_agg
        self.in_agg = previous or is_agg
        args = self.comma_list(self.or_expr) if not self.at_op(")") else []
        self.in_agg = previous
        self.expect_op(")")
        if is_agg and len(args) != 1:
            raise ArityError(f"{name}() takes exactly 1 argument, got {len(args)}")
        return Call(name, tuple(args))


def parse(source: str) -> Query:
    return _Parser(source).query()

"""Expression binding and evaluation, plus scalar functions."""

from typing import Callable

from .aggregate import AGGREGATES
from .errors import (AggregateError, ArityError, TypeMismatchError,
                     UnknownColumnError, UnknownFunctionError)
from .parser import (Binary, BoundColumn, Call, ColumnRef, IsNull, Literal,
                     OutColumn, Unary)
from .value import (and_, arith, compare_eq, compare_lt, negate, not_, or_,
                    type_of)


def _need_text(name: str, v: object) -> None:
    if v is not None and not isinstance(v, str):
        raise TypeMismatchError(f"{name}() needs TEXT, got {type_of(v)}")


def _concat(args: list[object]) -> object:
    for v in args:
        _need_text("concat", v)
    if any(v is None for v in args):
        return None
    return "".join(args)  # type: ignore[arg-type]


def _upper(args: list[object]) -> object:
    _need_text("upper", args[0])
    return None if args[0] is None else args[0].upper()  # type: ignore[union-attr]


def _lower(args: list[object]) -> object:
    _need_text("lower", args[0])
    return None if args[0] is None else args[0].lower()  # type: ignore[union-attr]


def _length(args: list[object]) -> object:
    _need_text("length", args[0])
    return None if args[0] is None else len(args[0])  # type: ignore[arg-type]


def _abs(args: list[object]) -> object:
    v = args[0]
    if v is None:
        return None
    if type_of(v) not in ("INT", "FLOAT"):
        raise TypeMismatchError(f"abs() needs a number, got {type_of(v)}")
    return abs(v)  # type: ignore[arg-type]


def _coalesce(args: list[object]) -> object:
    for v in args:
        if v is not None:
            return v
    return None


# name -> (min args, max args or None, implementation)
_SCALARS: dict[str, tuple[int, int | None, Callable[[list[object]], object]]] = {
    "concat": (2, None, _concat),
    "upper": (1, 1, _upper),
    "lower": (1, 1, _lower),
    "length": (1, 1, _length),
    "abs": (1, 1, _abs),
    "coalesce": (1, None, _coalesce),
}


def validate_call(name: str, argc: int) -> None:
    if name in AGGREGATES:
        return
    if name not in _SCALARS:
        raise UnknownFunctionError(f"unknown function {name!r}")
    low, high, _ = _SCALARS[name]
    if argc < low or (high is not None and argc > high):
        if high is None:
            need = f"at least {low}"
        else:
            need = f"exactly {low}"
        raise ArityError(f"{name}() takes {need} argument(s), got {argc}")


def is_aggregate(node: object) -> bool:
    return isinstance(node, Call) and node.name in AGGREGATES


def children(node: object) -> tuple:
    if isinstance(node, Unary):
        return (node.operand,)
    if isinstance(node, Binary):
        return (node.left, node.right)
    if isinstance(node, IsNull):
        return (node.operand,)
    if isinstance(node, Call):
        return node.args
    return ()


def contains_aggregate(node: object) -> bool:
    return is_aggregate(node) or any(contains_aggregate(c) for c in children(node))


def collect_aggregates(node: object, found: list[Call]) -> None:
    if is_aggregate(node):
        if node not in found:
            found.append(node)  # type: ignore[arg-type]
        return
    for child in children(node):
        collect_aggregates(child, found)


def rewrite(node: object, fn: Callable[[object], object | None]) -> object:
    """Top-down rewrite: fn returns a replacement, or None to recurse."""
    replaced = fn(node)
    if replaced is not None:
        return replaced
    if isinstance(node, Unary):
        return Unary(node.op, rewrite(node.operand, fn))
    if isinstance(node, Binary):
        return Binary(node.op, rewrite(node.left, fn), rewrite(node.right, fn))
    if isinstance(node, IsNull):
        return IsNull(rewrite(node.operand, fn), node.negated)
    if isinstance(node, Call):
        return Call(node.name, tuple(rewrite(a, fn) for a in node.args), node.star)
    return node


def bind(node: object, resolve: Callable[[ColumnRef], object]) -> object:
    """Resolve column references and validate function calls."""
    def step(n: object) -> object | None:
        if isinstance(n, ColumnRef):
            return resolve(n)
        if isinstance(n, Call):
            validate_call(n.name, len(n.args))
        return None
    return rewrite(node, step)


def _logical(v: object) -> bool | None:
    if v is not None and not isinstance(v, bool):
        raise TypeMismatchError(f"expected BOOL, got {type_of(v)}")
    return v


_COMPARE: dict[str, Callable[[object, object], bool | None]] = {
    "=": compare_eq,
    "<>": lambda a, b: not_(compare_eq(a, b)),
    "<": compare_lt,
    ">": lambda a, b: compare_lt(b, a),
    "<=": lambda a, b: not_(compare_lt(b, a)),
    ">=": lambda a, b: not_(compare_lt(a, b)),
}


def _eval_binary(node: Binary, row: list | None, out: list | None,
                 aggs: dict | None) -> object:
    left = evaluate(node.left, row, out, aggs)
    right = evaluate(node.right, row, out, aggs)
    if node.op == "AND":
        return and_(_logical(left), _logical(right))
    if node.op == "OR":
        return or_(_logical(left), _logical(right))
    if node.op in _COMPARE:
        return _COMPARE[node.op](left, right)
    return arith(node.op, left, right)


def _eval_call(node: Call, row: list | None, out: list | None,
               aggs: dict | None) -> object:
    if node.name in AGGREGATES:
        if aggs is None or node not in aggs:
            raise AggregateError(f"aggregate {node.name}() is not allowed here")
        return aggs[node]
    validate_call(node.name, len(node.args))
    args = [evaluate(a, row, out, aggs) for a in node.args]
    return _SCALARS[node.name][2](args)


def evaluate(node: object, row: list | None, out: list | None = None,
             aggs: dict | None = None) -> object:
    if isinstance(node, Literal):
        return node.value
    if isinstance(node, BoundColumn):
        return row[node.index]  # type: ignore[index]
    if isinstance(node, OutColumn):
        return out[node.index]  # type: ignore[index]
    if isinstance(node, Unary):
        value = evaluate(node.operand, row, out, aggs)
        return negate(value) if node.op == "-" else not_(_logical(value))
    if isinstance(node, Binary):
        return _eval_binary(node, row, out, aggs)
    if isinstance(node, IsNull):
        is_null = evaluate(node.operand, row, out, aggs) is None
        return (not is_null) if node.negated else is_null
    if isinstance(node, Call):
        return _eval_call(node, row, out, aggs)
    if isinstance(node, ColumnRef):
        raise UnknownColumnError(f"unbound column {node.name!r}")
    raise TypeError(f"cannot evaluate {node!r}")

"""Planner: Query -> Plan (an inspectable sequence of named stages)."""

import dataclasses
from collections.abc import Sequence
from typing import Iterator, overload

from .expr import contains_aggregate
from .parser import Query, Star


@dataclasses.dataclass(frozen=True)
class Stage:
    name: str
    payload: object = None


class Plan(Sequence):
    def __init__(self, query: Query, stages: list[Stage]) -> None:
        self.query = query
        self._stages = tuple(stages)

    @overload
    def __getitem__(self, index: int) -> Stage: ...
    @overload
    def __getitem__(self, index: slice) -> tuple[Stage, ...]: ...

    def __getitem__(self, index):  # type: ignore[no-untyped-def]
        return self._stages[index]

    def __len__(self) -> int:
        return len(self._stages)

    def __iter__(self) -> Iterator[Stage]:
        return iter(self._stages)

    @property
    def names(self) -> list[str]:
        return [s.name for s in self._stages]


def is_grouped(query: Query) -> bool:
    if query.group_by:
        return True
    exprs = [i.expr for i in query.items if not isinstance(i.expr, Star)]
    if query.having is not None:
        exprs.append(query.having)
    return any(contains_aggregate(e) for e in exprs)


def plan(query: Query) -> Plan:
    stages = [Stage("scan", query.table)]
    if query.join is not None:
        stages.append(Stage("join", query.join))
    if query.where is not None:
        stages.append(Stage("filter", query.where))
    if is_grouped(query):
        stages.append(Stage("group", query.group_by))
        stages.append(Stage("aggregate"))
    if query.having is not None:
        stages.append(Stage("having", query.having))
    stages.append(Stage("project", query.items))
    if query.distinct:
        stages.append(Stage("distinct"))
    if query.order_by:
        stages.append(Stage("sort", query.order_by))
    if query.offset is not None:
        stages.append(Stage("offset", query.offset))
    if query.limit is not None:
        stages.append(Stage("limit", query.limit))
    return Plan(query, stages)

"""Executor: runs a Plan against tables."""

import dataclasses
import functools
from typing import Callable, NamedTuple

from .aggregate import aggregate
from .errors import (AggregateError, AmbiguousColumnError, GroupingError,
                     TypeMismatchError, UnknownColumnError, UnknownTableError)
from .expr import (bind, children, collect_aggregates, contains_aggregate,
                   evaluate, is_aggregate, rewrite)
from .parser import (BoundColumn, Call, ColumnRef, OutColumn, Star, parse)
from .planner import Plan, plan
from .schema import Table
from .value import compare_lt, is_numeric


@dataclasses.dataclass(frozen=True)
class Result:
    columns: list[str]
    rows: list[list[object]]


class _Unit(NamedTuple):
    row: list | None
    aggs: dict | None


@dataclasses.dataclass
class _Bound:
    scope: list[tuple[str, str]]
    where: object | None
    on: object | None
    group_by: list
    having: object | None
    items: list[tuple[object, str]]
    order: list[tuple[object, bool]]
    calls: list[Call]


@dataclasses.dataclass
class _State:
    tables: dict[str, Table]
    bound: _Bound
    rows: list = dataclasses.field(default_factory=list)
    groups: list | None = None
    units: list[_Unit] | None = None
    out: list = dataclasses.field(default_factory=list)


def _table(tables: dict[str, Table], name: str) -> Table:
    if name not in tables:
        raise UnknownTableError(f"unknown table {name!r}")
    return tables[name]


def _make_resolver(scope: list[tuple[str, str]]) -> Callable[[ColumnRef], BoundColumn]:
    def resolve(ref: ColumnRef) -> BoundColumn:
        if ref.table is not None and all(t != ref.table for t, _ in scope):
            raise UnknownTableError(f"unknown table {ref.table!r}")
        hits = [i for i, (t, c) in enumerate(scope)
                if c == ref.name and (ref.table is None or t == ref.table)]
        label = ref.name if ref.table is None else f"{ref.table}.{ref.name}"
        if not hits:
            raise UnknownColumnError(f"unknown column {label!r}")
        if len(hits) > 1:
            raise AmbiguousColumnError(f"ambiguous column {label!r}")
        return BoundColumn(hits[0])
    return resolve


def _no_aggregate(node: object, where: str) -> None:
    if node is not None and contains_aggregate(node):
        raise AggregateError(f"aggregates are not allowed in {where}")


def _bind_items(query, scope, resolve) -> list[tuple[object, str]]:
    items: list[tuple[object, str]] = []
    for item in query.items:
        if isinstance(item.expr, Star):
            star = item.expr
            if star.table is not None and all(t != star.table for t, _ in scope):
                raise UnknownTableError(f"unknown table {star.table!r}")
            for i, (t, c) in enumerate(scope):
                if star.table is None or t == star.table:
                    items.append((BoundColumn(i), c))
            continue
        name = item.alias
        if name is None:
            name = item.expr.name if isinstance(item.expr, ColumnRef) else item.text
        items.append((bind(item.expr, resolve), name))
    return items


def _bind_order(query, items, resolve, grouped: bool) -> list[tuple[object, bool]]:
    names = [n for _, n in items]
    nodes = [n for n, _ in items]

    def by_output(n: object) -> object | None:
        if is_aggregate(n):
            return bind(n, resolve)
        if isinstance(n, ColumnRef) and n.table is None and n.name in names:
            return OutColumn(names.index(n.name))  # the alias wins over input columns
        if isinstance(n, ColumnRef):
            return resolve(n)
        return None

    def to_output(n: object) -> object | None:
        return OutColumn(nodes.index(n)) if n in nodes else None

    order = []
    for entry in query.order_by:
        node = rewrite(entry.expr, by_output)
        if not grouped and contains_aggregate(node):
            raise AggregateError("aggregates in ORDER BY need GROUP BY or a SELECT aggregate")
        if query.distinct:
            node = rewrite(node, to_output)
            _require_output_only(node)
        order.append((node, entry.desc))
    return order


def _require_output_only(node: object) -> None:
    if isinstance(node, BoundColumn):
        raise UnknownColumnError("with DISTINCT, ORDER BY may only use output columns")
    for child in children(node):
        _require_output_only(child)


def _check_grouped(node: object, group: list) -> None:
    if node in group or is_aggregate(node) or isinstance(node, OutColumn):
        return
    if isinstance(node, BoundColumn):
        raise GroupingError("column is neither aggregated nor in GROUP BY")
    for child in children(node):
        _check_grouped(child, group)


def _bind_query(plan_: Plan, tables: dict[str, Table]) -> _Bound:
    query = plan_.query
    scope = [(query.table, c.name) for c in _table(tables, query.table).columns]
    if query.join is not None:
        right = _table(tables, query.join.table)
        scope += [(query.join.table, c.name) for c in right.columns]
    resolve = _make_resolver(scope)
    where = bind(query.where, resolve) if query.where is not None else None
    on = bind(query.join.on, resolve) if query.join is not None else None
    group_by = [bind(g, resolve) for g in query.group_by]
    for node, label in ((where, "WHERE"), (on, "JOIN ON")):
        _no_aggregate(node, label)
    for g in group_by:
        _no_aggregate(g, "GROUP BY")
    items = _bind_items(query, scope, resolve)
    having = bind(query.having, resolve) if query.having is not None else None
    grouped = "group" in plan_.names
    order = _bind_order(query, items, resolve, grouped)
    if grouped:
        for node in [n for n, _ in items] + [having] + [n for n, _ in order]:
            if node is not None:
                _check_grouped(node, group_by)
    calls: list[Call] = []
    for node in [n for n, _ in items] + [having] + [n for n, _ in order]:
        if node is not None:
            collect_aggregates(node, calls)
    return _Bound(scope, where, on, group_by, having, items, order, calls)


def _truth(value: object) -> bool:
    if value is None:
        return False
    if not isinstance(value, bool):
        raise TypeMismatchError("a predicate must be BOOL")
    return value


def _key(value: object) -> tuple:
    """Grouping/DISTINCT identity: NULL equals NULL, numbers equal numerically."""
    if value is None:
        return ("NULL",)
    if isinstance(value, bool):
        return ("B", value)
    if is_numeric(value):
        return ("N", value)
    return ("T", value)


def _stage_scan(st: _State, stage) -> None:
    st.rows = list(_table(st.tables, stage.payload).rows)


def _stage_join(st: _State, stage) -> None:
    clause = stage.payload
    right = _table(st.tables, clause.table)
    joined: list = []
    for left_row in st.rows:
        matched = False
        for right_row in right.rows:
            combined = left_row + right_row
            if _truth(evaluate(st.bound.on, combined)):
                joined.append(combined)
                matched = True
        if not matched and clause.kind == "LEFT":
            joined.append(left_row + [None] * len(right.columns))
    st.rows = joined


def _stage_filter(st: _State, stage) -> None:
    st.rows = [r for r in st.rows if _truth(evaluate(st.bound.where, r))]


def _stage_group(st: _State, stage) -> None:
    if not st.bound.group_by:
        st.groups = [list(st.rows)]  # one group, even for empty input
        return
    groups: dict[tuple, list] = {}
    for row in st.rows:
        key = tuple(_key(evaluate(g, row)) for g in st.bound.group_by)
        groups.setdefault(key, []).append(row)
    st.groups = list(groups.values())


def _group_aggs(calls: list[Call], rows: list) -> dict:
    aggs: dict = {}
    for call in calls:
        if call.star:
            aggs[call] = aggregate(call.name, rows, star=True)
        else:
            values = [evaluate(call.args[0], r) for r in rows]
            aggs[call] = aggregate(call.name, values)
    return aggs


def _stage_aggregate(st: _State, stage) -> None:
    calls = st.bound.calls
    st.units = [_Unit(rows[0] if rows else None, _group_aggs(calls, rows))
                for rows in st.groups or []]


def _units(st: _State) -> list[_Unit]:
    if st.units is None:
        st.units = [_Unit(r, None) for r in st.rows]
    return st.units


def _stage_having(st: _State, stage) -> None:
    st.units = [u for u in _units(st)
                if _truth(evaluate(st.bound.having, u.row, None, u.aggs))]


def _stage_project(st: _State, stage) -> None:
    items = st.bound.items
    st.out = [([evaluate(n, u.row, None, u.aggs) for n, _ in items], u)
              for u in _units(st)]


def _stage_distinct(st: _State, stage) -> None:
    seen: set[tuple] = set()
    kept = []
    for entry in st.out:
        key = tuple(_key(v) for v in entry[0])
        if key not in seen:
            seen.add(key)
            kept.append(entry)
    st.out = kept


def _cmp(a: object, b: object) -> int:
    if compare_lt(a, b):
        return -1
    return 1 if compare_lt(b, a) else 0


def _stage_sort(st: _State, stage) -> None:
    order = st.bound.order
    keys = [[evaluate(n, u.row, o, u.aggs) for n, _ in order] for o, u in st.out]
    idx = list(range(len(st.out)))
    for k in reversed(range(len(order))):  # stable passes, last key first
        present = [i for i in idx if keys[i][k] is not None]
        nulls = [i for i in idx if keys[i][k] is None]
        present.sort(key=functools.cmp_to_key(lambda a, b: _cmp(keys[a][k], keys[b][k])),
                     reverse=order[k][1])
        idx = present + nulls  # NULL last for both ASC and DESC
    st.out = [st.out[i] for i in idx]


def _stage_offset(st: _State, stage) -> None:
    st.out = st.out[stage.payload:]


def _stage_limit(st: _State, stage) -> None:
    st.out = st.out[:stage.payload]


_HANDLERS: dict[str, Callable[[_State, object], None]] = {
    "scan": _stage_scan,
    "join": _stage_join,
    "filter": _stage_filter,
    "group": _stage_group,
    "aggregate": _stage_aggregate,
    "having": _stage_having,
    "project": _stage_project,
    "distinct": _stage_distinct,
    "sort": _stage_sort,
    "offset": _stage_offset,
    "limit": _stage_limit,
}


def execute_plan(plan: Plan, tables: dict[str, Table]) -> Result:
    state = _State(tables, _bind_query(plan, tables))
    for stage in plan:
        _HANDLERS[stage.name](state, stage)
    return Result([n for _, n in state.bound.items], [o for o, _ in state.out])


def execute(query: str, tables: dict[str, Table]) -> Result:
    return execute_plan(plan(parse(query)), tables)

"""Command line interface: python -m microdb --table NAME=PATH QUERY"""

import csv
import sys

from .errors import MicroDBError
from .executor import Result, execute
from .schema import COLUMN_TYPES, Column, Table


class _UsageError(Exception):
    pass


def _parse_args(argv: list[str]) -> tuple[list[tuple[str, str]], str]:
    specs: list[tuple[str, str]] = []
    positional: list[str] = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--table":
            i += 1
            if i >= len(argv):
                raise _UsageError("--table needs NAME=PATH")
            name, sep, path = argv[i].partition("=")
            if not sep or not name or not path:
                raise _UsageError(f"bad --table value {argv[i]!r}, expected NAME=PATH")
            specs.append((name, path))
        elif arg.startswith("--"):
            raise _UsageError(f"unknown option {arg!r}")
        else:
            positional.append(arg)
        i += 1
    if not specs:
        raise _UsageError("at least one --table is required")
    if len(positional) != 1:
        raise _UsageError("exactly one QUERY argument is required")
    return specs, positional[0]


def _parse_header(fields: list[str]) -> list[Column]:
    columns = []
    for field in fields:
        name, sep, ctype = field.rpartition(":")
        ctype = ctype.strip().upper()
        if not sep or not name or ctype not in COLUMN_TYPES:
            raise _UsageError(f"malformed header field {field!r}, expected name:TYPE")
        columns.append(Column(name, ctype))
    return columns


def _convert_cell(field: str, ctype: str) -> object:
    # An empty field is NULL; two single quotes ('') mean the empty string.
    if field == "":
        return None
    try:
        if ctype == "TEXT":
            return "" if field == "''" else field
        if ctype == "INT":
            return int(field)
        if ctype == "FLOAT":
            return float(field)
        if field.lower() in ("true", "false"):
            return field.lower() == "true"
    except ValueError:
        pass
    raise _UsageError(f"invalid {ctype} value {field!r}")


def _read_csv(path: str) -> list[list[str]]:
    try:
        with open(path, newline="", encoding="utf-8-sig") as handle:
            return list(csv.reader(handle))
    except (OSError, UnicodeDecodeError, csv.Error) as exc:
        raise _UsageError(f"cannot read {path!r}: {exc}") from exc


def _load_table(name: str, path: str) -> Table:
    lines = _read_csv(path)
    if not lines:
        raise _UsageError(f"{path!r} is empty, a header line is required")
    columns = _parse_header(lines[0])
    rows: list[list[object]] = []
    for raw in lines[1:]:
        if not raw:
            if len(columns) != 1:
                continue
            raw = [""]  # a blank line is one NULL cell in a one-column table
        if len(raw) != len(columns):
            rows.append(list(raw))  # Table reports the length mismatch
        else:
            rows.append([_convert_cell(f, c.type) for f, c in zip(raw, columns)])
    return Table(name, columns, rows)


def _format_value(value: object) -> str:
    if value is None:
        return ""
    if isinstance(value, bool):
        return "true" if value else "false"
    text = str(value)
    if any(ch in text for ch in ',"\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def render(result: Result) -> str:
    lines = [",".join(_format_value(c) for c in result.columns)]
    lines += [",".join(_format_value(v) for v in row) for row in result.rows]
    return "".join(line + "\n" for line in lines)


def _write_stdout(text: str) -> None:
    out = sys.stdout
    try:
        out.reconfigure(newline="\n", encoding="utf-8")  # type: ignore[union-attr]
    except (AttributeError, ValueError, OSError):
        pass
    out.write(text)
    out.flush()


def main(argv: list[str] | None = None) -> int:
    args = sys.argv[1:] if argv is None else list(argv)
    try:
        specs, query = _parse_args(args)
        tables = {name: _load_table(name, path) for name, path in specs}
        output = render(execute(query, tables))
    except _UsageError as exc:
        print(f"usage error: {exc}", file=sys.stderr)
        return 2
    except MicroDBError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 3
    _write_stdout(output)
    return 0


if __name__ == "__main__":
    sys.exit(main())
